with flattened_attrs as (select id, effective_from, tier_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, array_min(tier_prices) as lowest_price from price_tiers where effective_from between '2025-07-03' and '2025-09-18') select date_trunc('week', effective_from) as week_start, percentile_approx(lowest_price, array(0.25, 0.5, 0.75)) as lowest_price_quartiles, round(avg(lowest_price), 2) as avg_lowest_price, approx_percentile(lowest_price, 0.9) as lowest_price_p90 from flattened_attrs group by 1;
